// Generated by /ship test coverage audit.
// Value: protects=POC-document and checklist-image uploads refuse HTML/SVG/XML/JS (stored XSS on the app origin) and missing fields, writing nothing;
//   fails_when=either controller drops or reorders its isActiveContentFile / required-field guard;
//   why_new=uploadSafety.test covers the helper only; no test proves the two upload handlers call it; seam=none
import { describe, it, expect, jest } from '@jest/globals';
import type { Request, Response, NextFunction } from 'express';

const mockMkdir = jest.fn();
const mockWrite = jest.fn();
jest.mock('fs', () => ({ ...jest.requireActual<typeof import('fs')>('fs'), mkdirSync: mockMkdir, writeFileSync: mockWrite }));

const mockExecute = jest.fn(async () => ({ rows: [], rowCount: 1 }));
jest.mock('../../config/database', () => ({ query: jest.fn(), execute: mockExecute, transaction: jest.fn() }));
jest.mock('../../services/authService', () => ({ authService: {} }));

import { pocDocumentsController } from '../../controllers/pocDocumentsController';
import { migrationChecklistController } from '../../controllers/migrationChecklistController';

type Handler = (req: Request, res: Response, next: NextFunction) => void;

const HANDLERS: [string, Handler][] = [
  ['pocDocumentsController.upload', pocDocumentsController.upload as Handler],
  ['migrationChecklistController.uploadImage', migrationChecklistController.uploadImage as Handler],
];

async function call(handler: Handler, body: Record<string, unknown>) {
  const json = jest.fn();
  const status = jest.fn((_code: number) => ({ json }));
  const res = { status, json } as unknown as Response;
  handler({ params: { projectId: 'p1' }, body } as unknown as Request, res, jest.fn() as unknown as NextFunction);
  await new Promise((r) => setImmediate(r));
  return { status, json };
}

describe('upload controllers reject active content', () => {
  const mkdir = mockMkdir;
  const write = mockWrite;

  describe.each(HANDLERS)('%s', (_name, handler) => {
    it.each(['evil.html', 'logo.SVG', 'feed.xml', 'x.js', 'page.htm.'])('refuses %s with 400 and writes nothing', async (fileName) => {
      const { status } = await call(handler, { fileName, fileData: 'PHNjcmlwdD4=' });
      expect(status).toHaveBeenCalledWith(400);
      expect(write).not.toHaveBeenCalled();
      expect(mkdir).not.toHaveBeenCalled();
      expect(mockExecute).not.toHaveBeenCalled();
    });

    it.each([
      [{ fileData: 'AAAA' }],
      [{ fileName: 'a.png' }],
    ])('refuses a body missing fileName or fileData (%j)', async (body) => {
      const { status } = await call(handler, body);
      expect(status).toHaveBeenCalledWith(400);
      expect(write).not.toHaveBeenCalled();
    });

    it('still stores an ordinary image/PDF', async () => {
      const { status, json } = await call(handler, { fileName: 'screenshot.png', fileData: 'iVBORw0KGgo=' });
      expect(status).not.toHaveBeenCalled();
      expect(write).toHaveBeenCalledTimes(1);
      expect(String(write.mock.calls[0][0])).toMatch(/\.png$/);
      expect(json).toHaveBeenCalledWith(expect.objectContaining({ success: true }));
    });
  });
});
